/*
 * A236684  Values of c of triples (a,b,c) of positive integers such that 1/a
 *          + 1/b + 1/c = 1/2 and a <= b <= c. Listed with multiplicity,
 *          corresponding to solutions (a,b,c) listed in lexicographic order.
 * https://oeis.org/A236684
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   a(n) is the n-th c‑value in lexicographic order of solutions to
 *            * 1/a + 1/b + 1/c = 1/2 with a ≤ b ≤ c. The solutions are
 *            generated by * a small search over a and b, after which c is
 *            obtained by * c = 2ab / (ab − 2a − 2b). The enumeration stops
 *            when further a values * cannot produce any b ≥ a
 * Range:     u8 n <= 10, u16 n <= 10, u32 n <= 10, u64 n <= 10, u128 n <= 10,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>

seq_t a(idx_t n) {
    /* static array to hold all c values (there are only 10 for this equation) */
    static seq_t vals[256];
    static size_t count = 0;

    if (count == 0) {
        size_t idx = 0;
        for (seq_t a = 3; ; ++a) {
            /* upper bound for b:  b ≤ floor(4a/(a-2)) */
            seq_t bmax = (4 * a) / (a - 2);
            if (bmax < a) break;   /* no further a will produce a valid b */

            for (seq_t b = a; b <= bmax; ++b) {
                seq_t d = a * b - 2 * a - 2 * b;   /* denominator of 1/c */
                if (d <= 0) continue;              /* would give non‑positive c */

                seq_t N = 2 * a * b;                /* numerator */

                if (N % d != 0) continue;          /* not an integer c */

                seq_t c = N / d;
                if (c < b) continue;                /* respect a ≤ b ≤ c */

                vals[idx++] = c;
            }
        }
        count = idx;
    }

    if (n == 0 || (idx_t)(n - 1) >= count) {
        return 0;          /* undefined for out‑of‑range n */
    }
    return vals[n - 1];
}
